 "content": "from collections import deque


def transform(grid):
    """Fill background regions fully enclosed by the linework with color 4."""
    h, w = len(grid), len(grid[0])
    bg = next(value for row in grid for value in row if value not in (4,))
    # The background is the most frequent color; other colors are barriers.
    from collections import Counter
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == bg:
                seen.add((nr, nc)); q.append((nr, nc))
    return [[4 if value == bg and (r, c) not in seen else value
             for c, value in enumerate(row)]
            for r, row in enumerate(grid)]

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
